/** Case 9 fallback. T is the bisected mixture time, with no rounding and no 15-minute lead. */
export function estimateCase9Delay(delays, dayNumbers) {
    if (delays.length < 3 || delays.length !== dayNumbers.length)
        return null;
    const medianDelay = medianOf(delays);
    const mad = medianOf(delays.map((delay) => Math.abs(delay - medianDelay)));
    const scale = Math.max(15, mad);
    const newestDay = Math.max(...dayNumbers);
    const rawWeights = delays.map((delay, index) => {
        const age = newestDay - dayNumbers[index];
        const u = Math.exp(Math.max(-700, -Math.log(2) * age / 7));
        const distance = (delay - medianDelay) / (2 * scale);
        const r = 0.5 + 0.5 / (1 + distance * distance);
        return u * r;
    });
    const weightSum = rawWeights.reduce((sum, weight) => sum + weight, 0);
    if (!(weightSum > 0))
        return null;
    const weights = rawWeights.map((weight) => weight / weightSum);
    const mu = delays.reduce((sum, delay, index) => sum + weights[index] * delay, 0);
    const variance = delays.reduce((sum, delay, index) => {
        const delta = delay - mu;
        return sum + weights[index] * delta * delta;
    }, 0);
    const sd = Math.sqrt(variance);
    const dRatio = sd + mu > 0 ? sd / (sd + mu) : 0;
    const h = Math.max(0.01, Math.min(45, Math.max(5, 0.25 * sd), mu / 3));
    const q = 0.5 - 0.25 * dRatio;
    const logistic = (x) => 1 / (1 + Math.exp(Math.max(-40, Math.min(40, -x))));
    const mixture = (t) => delays.reduce((total, leakAt, index) => {
        const base = logistic(-leakAt / h);
        const denom = 1 - base;
        const grown = denom !== 0 ? (logistic((t - leakAt) / h) - base) / denom : 0;
        return total + weights[index] * grown;
    }, 0);
    let lo = 0;
    let upper = Math.max(...delays) + 12 * h;
    for (let step = 0; step < 36; step++) {
        const mid = (lo + upper) / 2;
        if (mixture(mid) < q)
            lo = mid;
        else
            upper = mid;
    }
    return (lo + upper) / 2;
}
function medianOf(values) {
    const sorted = [...values].sort((a, b) => a - b);
    const mid = Math.floor(sorted.length / 2);
    return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
}
